#[allow(non_snake_case)]
fn __rt_PremiumSubscriptionOption() {
    samples::__stack(move || {
        let v = samples::s_PremiumSubscriptionOption(3);
        let mut out = Vec::new();
        v.store_boxed(&mut out);
        let w = PremiumSubscriptionOption::parse(&out).expect("PremiumSubscriptionOption parse");
        assert_eq!(v, w);
        let mut out = Vec::new();
        v.store(&mut out);
        let w = PremiumSubscriptionOption::parse_bare(&out).expect("PremiumSubscriptionOption bare parse");
        assert_eq!(v, w);
    });
}

